    if t == 'assistant':
        content = entry.get('message', {}).get('content', [])
        texts = [c['text'] for c in content if c.get('type') == 'text']
        tools = [{'name': c.get('name'), 'input_keys': list(c.get('input', {}).keys()) if isinstance(c.get('input'), dict) else None} for c in content if c.get('type') == 'tool_use']
        print(f"ASSISTANT: texts={texts[:1]}, tools={tools}")
    elif t == 'user':
        content = entry.get('message', {}).get('content', [])
        if isinstance(content, list):
            for c in content:
                if c.get('type') == 'tool_result':
                    result_content = str(c.get('content', ''))
                    if len(result_content) > 500:
                        result_content = result_content[:200] + '...'
                    print(f"  TOOL_RESULT: {result_content[:300]}")
                elif c.get('type') == 'image':
                    print(f"  IMAGE (sent to worker)")
                elif c.get('type') == 'text':
                    print(f"  USER_TEXT: {str(c.get('text', ''))[:200]}")
    elif t == 'rate_limit_event':
        print(f"RATE_LIMIT: {json.dumps(entry, ensure_ascii=False)[:300]}")
    else:
        print(f"{t}: {json.dumps(entry, ensure_ascii=False)[:200]}")
